int main(int argc, char** argv) {
    std::ios::sync_with_stdio(false);
    if (argc < 2) {
        return 1;
    }
    std::size_t n = 0;
    try {
        std::size_t pos = 0;
        std::string s(argv[1]);
        unsigned long long parsed = std::stoull(s, &pos);
        while (pos < s.size() && (s[pos] == ' ' || s[pos] == '\t' || s[pos] == '\n' || s[pos] == '\r')) {
            ++pos;
        }
        if (pos != s.size() || s.find('-') != std::string::npos) {
            return 1;
        }
        n = static_cast<std::size_t>(parsed);
    } catch (...) {
        return 1;
    }
    const std::uint64_t base = 1000000000ULL * 1000000000ULL;
    std::vector<std::uint64_t> a(1, 1);
    std::vector<std::uint64_t> b(1, 1);
    for (std::size_t step = 0; step < n; ++step) {
        std::uint64_t carry = 0;
        std::size_t len = b.size();
        if (a.size() < len) {
            a.resize(len, 0);
        }
        for (std::size_t i = 0; i < len; ++i) {
            std::uint64_t sum = a[i] + b[i] + carry;
            if (sum >= base) {
                a[i] = sum - base;
                carry = 1;
            } else {
                a[i] = sum;
                carry = 0;
            }
        }
        if (carry > 0) {
            a.push_back(carry);
        }
        std::swap(a, b);
    }
    std::size_t idx = a.size() - 1;
    std::cout << a[idx];
    while (idx > 0) {
        --idx;
        std::cout << std::setw(18) << std::setfill('0') << a[idx];
    }
    std::cout << '\n';
    return 0;
}
