use std::io::Write;

fn main() {
    let mut args = std::env::args();
    let arg = match args.nth(1) {
        Some(s) => s,
        None => std::process::exit(1),
    };
    let n: usize = match arg.trim().parse() {
        Ok(v) => v,
        Err(_) => std::process::exit(1),
    };
    let base: u64 = 1000000000u64 * 1000000000u64;
    let mut a: Vec<u64> = vec![1];
    let mut b: Vec<u64> = vec![1];
    for _ in 0..n {
        let mut carry: u64 = 0;
        let len = b.len();
        if a.len() < len {
            a.resize(len, 0);
        }
        for i in 0..len {
            let sum = a[i] + b[i] + carry;
            if sum >= base {
                a[i] = sum - base;
                carry = 1;
            } else {
                a[i] = sum;
                carry = 0;
            }
        }
        if carry > 0 {
            a.push(carry);
        }
        std::mem::swap(&mut a, &mut b);
    }
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    let mut idx = a.len() - 1;
    write!(out, "{}", a[idx]).unwrap();
    while idx > 0 {
        idx -= 1;
        write!(out, "{:018}", a[idx]).unwrap();
    }
    writeln!(out).unwrap();
}
