#include <cstddef>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <string>
#include <utility>
#include <vector>

namespace {

using Big = std::vector<std::uint64_t>;
const std::uint64_t BASE = 1000000000ULL;

Big add_big(const Big& a, const Big& b) {
    std::size_t n = a.size() > b.size() ? a.size() : b.size();
    Big out;
    out.reserve(n + 1);
    std::uint64_t carry = 0;
    std::size_t i = 0;
    while (i < n || carry > 0) {
        std::uint64_t av = i < a.size() ? a[i] : 0;
        std::uint64_t bv = i < b.size() ? b[i] : 0;
        std::uint64_t s = av + bv + carry;
        if (s >= BASE) {
            out.push_back(s - BASE);
            carry = 1;
        } else {
            out.push_back(s);
            carry = 0;
        }
        ++i;
    }
    return out;
}

Big sub_big(const Big& a, const Big& b) {
    Big out;
    out.reserve(a.size());
    std::uint64_t borrow = 0;
    for (std::size_t i = 0; i < a.size(); ++i) {
        std::uint64_t av = a[i];
        std::uint64_t bv = (i < b.size() ? b[i] : 0) + borrow;
        if (av < bv) {
            out.push_back(av + BASE - bv);
            borrow = 1;
        } else {
            out.push_back(av - bv);
            borrow = 0;
        }
    }
    while (!out.empty() && out.back() == 0) {
        out.pop_back();
    }
    return out;
}

Big mul_big(const Big& a, const Big& b) {
    if (a.empty() || b.empty()) {
        return Big();
    }
    Big out(a.size() + b.size(), 0);
    std::uint64_t* op = out.data();
    const std::uint64_t* ap = a.data();
    const std::uint64_t* bp = b.data();
    std::size_t alen = a.size();
    std::size_t blen = b.size();
    for (std::size_t i = 0; i < alen; ++i) {
        std::uint64_t ai = ap[i];
        std::uint64_t carry = 0;
        for (std::size_t j = 0; j < blen; ++j) {
            std::uint64_t cur = op[i + j] + ai * bp[j] + carry;
            op[i + j] = cur % BASE;
            carry = cur / BASE;
        }
        op[i + blen] += carry;
    }
    while (!out.empty() && out.back() == 0) {
        out.pop_back();
    }
    return out;
}

