fn add_big(a: &[u64], b: &[u64]) -> Vec<u64> {
    let n = if a.len() > b.len() { a.len() } else { b.len() };
    let mut out = Vec::with_capacity(n + 1);
    let mut carry: u64 = 0;
    let mut i = 0;
